THOUGHT: I can see a potential issue in the dialConnection function. When multiple IP addresses are resolved for a hostname and all connection attempts fail, the error message only reports the last error that occurred. This can be misleading because it doesn't represent all the failures.

The problem is in the loop where it waits for either a successful connection or all errors. When it gets an error from errChan, it overwrites the previous error value. By the end of the loop, only the last error is retained, even though multiple connection attempts may have failed with different errors.

Let me create a fix that collects all errors and reports them in the final error message.

```bash
cat <<'EOF' > tds_fixed.go
package mssql

import (
	"context"
	"database/sql/driver"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
	"sort"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf16"
	"unicode/utf8"

	"github.com/denisenkom/go-mssqldb/internal/querytext"
	"github.com/denisenkom/go-mssqldb/msdsn"
	"github.com/golang-sql/sqlexp"
)

// ... (other code remains the same until the dialConnection function)

func dialConnection(ctx context.Context, c *Connector, p msdsn.Config) (conn net.Conn, err error) {
	var ips []net.IP
	ip := net.ParseIP(p.Host)
	if ip == nil {
		ips, err = net.LookupIP(p.Host)
		if err != nil {
			return
		}
	} else {
		ips = []net.IP{ip}
	}
	if len(ips) == 1 {
		d := c.getDialer(&p)
		addr := net.JoinHostPort(ips[0].String(), strconv.Itoa(int(resolveServerPort(p.Port))))
		conn, err = d.DialContext(ctx, "tcp", addr)

	} else {
		//Try Dials in parallel to avoid waiting for timeouts.
		connChan := make(chan net.Conn, len(ips))
		errChan := make(chan error, len(ips))
		portStr := strconv.Itoa(int(resolveServerPort(p.Port)))
		for _, ip := range ips {
			go func(ip net.IP) {
				d := c.getDialer(&p)
				addr := net.JoinHostPort(ip.String(), portStr)
				conn, err := d.DialContext(ctx, "tcp", addr)
				if err == nil {
					connChan <- conn
				} else {
					errChan <- err
				}
			}(ip)
		}
		// Wait for either the *first* successful connection, or all the errors
		var errs []error
	wait_loop:
		for i := range ips {
			select {
			case conn = <-connChan:
				// Got a connection to use, close any others
				go func(n int) {
					for i := 0; i < n; i++ {
						select {
						case conn := <-connChan:
							conn.Close()
						case <-errChan:
						}
					}
				}(len(ips) - i - 1)
				// Remove any earlier errors we may have collected
				errs = nil
				break wait_loop
			case err = <-errChan:
				errs = append(errs, err)
			}
		}
		// Can't do the usual err != nil check, as it is possible to have gotten an error before a successful connection
		if conn == nil {
			if len(errs) > 0 {
				// Sort errors to make the most meaningful error appear first
				sort.Slice(errs, func(i, j int) bool {
					return errs[i].Error() < errs[j].Error()
				})

				if len(errs) == 1 {
					f := "unable to open tcp connection with host '%v:%v': %v"
					return nil, fmt.Errorf(f, p.Host, resolveServerPort(p.Port), errs[0].Error())
				} else {
					// Collect all error messages
					var errMsgs []string
					for _, e := range errs {
						errMsgs = append(errMsgs, e.Error())
					}
					f := "unable to open tcp connection with host '%v:%v': Multiple connection attempts failed with errors: %v"
					return nil, fmt.Errorf(f, p.Host, resolveServerPort(p.Port), strings.Join(errMsgs, "; "))
				}
			} else {
				f := "unable to open tcp connection with host '%v:%v': Unknown error"
				return nil, fmt.Errorf(f, p.Host, resolveServerPort(p.Port))
			}
		}
	}
	return conn, err
}

